34: function getStats(index=state.car){const base=cars[index],install=state.cars[index].owned;let hp=base.hp,max=base.max,hand=base.hand,acc=base.acc;for(const cat of categoryData)for(const item of cat.items)if(install[cat.id]===item[0]){hp+=item[4];max+=Math.round(item[4]*.29);hand+=item[6];acc-=item[5]*.018}return{hp:Math.round(hp),max:Math.round(max),hand:Math.min(99,hand),acc:Math.max(2.4,acc)}}
