42: function renderTracks(){const list=$('#trackList');list.innerHTML=tracks.map((t,i)=>`<button class="track-card ${i===selectedTrack?'active':''}" data-track="${i}" data-number="0${i+1}"><div class="track-card-top"><span class="track-number">0${i+1} / ТРАССА</span><span class="track-difficulty"><i>${'●'.repeat(i+1)}</i>${'○'.repeat(2-i)} ${t.diff}</span></div><h3>${t.place}</h3><p>${t.desc}</p><div class="track-meta"><span>ДЛИНА <b>${t.length}</b></span><span>КРУГОВ <b>02</b></span><span>₽ <b>${fmt(t.reward)}</b></span></div></button>`).join('');list.onclick=e=>{const b=e.target.closest('[data-track]');if(b){selectedTrack=+b.dataset.track;renderTracks();updateTrackPreview()}};updateTrackPreview()}
