44: function renderCategories(){const grouped=['ПЕРФОМАНС','МОТОР','ХОДОВАЯ','СТИЛЬ'];$('#tuningCategories').innerHTML=grouped.map(g=>`<div class="category-heading">${g}</div>`+categoryData.filter(c=>c.group===g).map(c=>`<button class="category-btn ${state.category===c.id?'active':''}" data-category="${c.id}"><span class="cat-ico">${c.icon}</span>${c.name}<small>›</small></button>`).join('')).join('');$('#tuningCategories').onclick=e=>{const b=e.target.closest('[data-category]');if(b){state.category=b.dataset.category;renderTuning()}}}
45: function renderTuning(){renderCategories();const cat=categoryData.find(c=>c.id===state.category)||categoryData[0];$('#partsEyebrow').textContent=cat.group==='СТИЛЬ'?'СТИЛЬ И ВНЕШНИЙ ВИД':'УЛУЧШЕНИЕ ХАРАКТЕРИСТИК';$('#partsTitle').textContent=cat.name.toUpperCase();$('#partsGrid').innerHTML=cat.items.map((it,i)=>{const owned=carState().owned[cat.id]===it[0],afford=state.money>=it[3];return`<article class="part-card ${owned?'owned':''}"><span class="part-level">${owned?'УСТАНОВЛЕНО':`STAGE 0${i+1}`}</span><div class="part-icon">${cat.icon}</div><h3>${it[1]}</h3><p>${it[2]}</p><div class="part-stats">${it[4]?`<span>+${it[4]} Л.С.</span>`:''}${it[5]?`<span>−${it[5]}% РАЗГОН</span>`:''}${it[6]?`<span>+${it[6]} ХОД</span>`:''}${!it[4]&&!it[5]&&!it[6]?'<span>ВНЕШНИЙ ВИД</span>':''}</div><div class="part-footer"><span class="part-price">${fmt(it[3])} <small>₽</small></span><button class="part-buy ${owned?'owned-btn':''}" data-buy="${it[0]}" ${owned||!afford?'disabled':''}>${owned?'УСТАНОВЛЕНО':afford?'УСТАНОВИТЬ':'НЕ ХВАТАЕТ ₽'}</button></div></article>`}).join('');$('#partsGrid').onclick=e=>{const b=e.target.closest('[data-buy]');if(b)buyPart(cat,b.dataset.buy)} }
46: function openView(name){$$('.view').forEach(v=>v.classList.remove('active'));const el=$(`#${name}View`);if(el)el.classList.add('active');$('#crumbTitle').textContent=({garage:'ГАРАЖ',tuning:'ТЮНИНГ',race:'ГОНОЧНЫЙ КЛУБ',raceGame:'ЗАЕЗД'})[name]||'ГАРАЖ';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='tuning')renderTuning();if(name==='race'){renderTracks();race3d?.resize()}}
47: function buyPart(cat,key){const it=cat.items.find(x=>x[0]===key);if(!it||carState().owned[cat.id]===key)return;if(state.money<it[3])return toast('Не хватает денег на эту деталь');state.money-=it[3];carState().owned[cat.id]=key;if(cat.id==='paint'){const colors={p1:0xff5b35,p2:0x454954,p3:0xf0f0e9,p4:0xd8fd57};carState().color=colors[key];updateCar3d()}if(it[4]>0&&race&&engineOsc)refreshEngineAudio(race.speed);save();renderBalance();renderGarage();renderTuning();toast('Деталь куплена. Механики уже работают!');mechanicAnimation(cat.id)}
48: function mechanicAnimation(cat){if(!activeCarModel||animating)return;animating=true;const m=activeCarModel;const hood=m.userData.hood,engine=m.userData.engine;const engineHome=engine?.userData.home?.clone()||engine?.position.clone();const start=performance.now(),duration=cat==='engine'?5200:3300;const ease=t=>t*t*(3-2*t);const between=(a,b,t)=>a+(b-a)*ease(Math.max(0,Math.min(1,t)));const tick=now=>{const t=Math.min(1,(now-start)/duration);if(hood){const open=cat==='engine'?.72:.46,phase=t<.16?t/.16:t<.84?1:(1-t)/.16;hood.rotation.x=-open*ease(Math.max(0,Math.min(1,phase)))}if(engine&&engineHome&&cat==='engine'){const keyframes=[[0,0,.0],[.22,0,0],[.34,.5,.18],[.46,.5,.72],[.58,-1.25,1.1],[.68,-1.25,1.1],[.8,.48,.35],[.9,.12,.08],[1,0,0]];let i=0;while(i<keyframes.length-2&&t>keyframes[i+1][0])i++;const a=keyframes[i],b=keyframes[i+1],u=(t-a[0])/(b[0]-a[0]);engine.position.set(engineHome.x,engineHome.y+between(a[1],b[1],u),engineHome.z+between(a[2],b[2],u))}if(t<1)requestAnimationFrame(tick);else{if(hood)hood.rotation.x=0;if(engine&&engineHome)engine.position.copy(engineHome);animating=false}};requestAnimationFrame(tick)}
